mapper.select:
SELECT contest_id, version, user_id, rank_no, row_position, score,
       correct_count, answered_count, handed_in, created_at
FROM contest_rank_entry
WHERE contest_id = #{contestId} AND version = #{version}
ORDER BY row_position ASC
LIMIT #{offset}, #{pageSize}

mapper.delete:
DELETE FROM contest_rank_entry
WHERE contest_id = #{contestId}
  AND version NOT IN (
      SELECT retained.version FROM (
          SELECT DISTINCT version
          FROM contest_rank_entry
          WHERE contest_id = #{contestId} AND version <= #{publishedVersion}
          ORDER BY version DESC
          LIMIT 2
      ) retained
  )

      AND version <> #{protectedCandidate}

LIMIT #{batchSize}
